// Classic Cart Studio console backup and restore engine tests: the console's Windows USB driver (CcsBackup.Driver). Copyright (C) 2026 Rance9. GPL-3.0-or-later.
// Every PC here is a SimulatedDriverStore (memory only) changed by SimulatedDriverActions; no driver, certificate, device or setting on this
// PC is read or changed by the "driver" group. The "driver-real" group reads this PC's driver state (read only) and runs only with
// --real-driver-store; it prints counts, never names, thumbprints or device ids.
using CcsBackup.Driver;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using static CcsBackup.Tests.Program;

namespace CcsBackup.Tests
{
    static partial class Tests
    {
        sealed class DrvPc { public SimulatedDriverStore Pc; public SimulatedDriverActions Act; public SetupContext Ctx; public string Dir; }

        static DrvPc NewPc(string name, bool consoleConnected = true)
        {
            var dir = NewDir("driver-" + name);
            var pc = new SimulatedDriverStore();
            pc.AddCertificate(CertStore.Root, SimulatedDriverStore.FakeThumbprint("root-a"), "CN=Example Root CA");          // unrelated: must never be touched
            pc.AddCertificate(CertStore.TrustedPublisher, SimulatedDriverStore.FakeThumbprint("pub-a"), "CN=Example Publisher");
            pc.AddPackage("othermouse.inf", "Contoso", "mouhid", null, SimulatedDriverStore.FakeThumbprint("contoso"), @"USB\VID_045E&PID_0040");
            if (consoleConnected) pc.AddDevice("5&1a2b3c4d&0&2", true);
            var act = new SimulatedDriverActions(pc);
            // SimulatedDriverActions reproduces the pinned Hakchi helper, so these cases run its plan (Workbench's own package: TestsDriverAdapter.cs)
            return new DrvPc { Pc = pc, Act = act, Dir = dir, Ctx = new SetupContext { Store = pc, Actions = act, Ledger = new DriverLedger(dir), Elevation = ElevationState.CanElevate, ToolVersion = "test", Plan = DriverSetupPlan.PinnedHakchi() } };
        }

        static List<string> RecordFiles(DrvPc p) => Directory.Exists(p.Ctx.Ledger.Folder) ? Directory.GetFiles(p.Ctx.Ledger.Folder, "usb-driver-*.json").ToList() : new List<string>();
        static DriverRecord Installed(DrvPc p) { var o = DriverSetup.Run(p.Ctx); if (o.Record == null || !o.Record.Installed) throw new Exception("setup did not install: " + o.Result + " " + o.Message); return o.Record; }
        static RemovalDecision Decide(DrvPc p, DriverRecord r, DriverUsage u = null) => Eligibility.Evaluate(r, DriverSnapshot.Capture(p.Pc), u ?? new DriverUsage());
        static bool Only(RemovalDecision d, RetainReason r) => !d.Offer && d.Reasons.SequenceEqual(new[] { r });   // that reason and no other
        static int Unrelated(SimulatedDriverStore pc) => pc.CertificateList.Count(c => c.Subject.StartsWith("CN=Example")) + pc.PackageList.Count(x => x.OriginalName == "othermouse.inf");

        public static void Driver()
        {
            Texts();
            InfAndIds();

            // ---------------------------------------------------------- absent driver: setup, close offer, removal
            {
                var p = NewPc("absent");
                var a = DriverSetup.Assess(p.Pc);
                Check(a.Kind == AssociationKind.None && a.SetupNeeded && !a.Reusable && a.Message == DriverText.SetupBody, "absent driver: setup needed, the setup text (" + a.Kind + ")");
                var details = DriverText.SetupDetails(DriverSetupPlan.PinnedHakchi());
                Check(details.Any(x => x.Contains("Trusted Root Certification Authorities") && x.Contains("Trusted Publishers") && x.Contains("libwdi autogenerated") && x.Contains("private key is deleted"))
                      && details.Any(x => x.Contains("nintendo_classic.inf")) && details.Any(x => x.Contains("System32")) && details.Any(x => x.Contains("restore-point")),
                      "the details before consent name the actual PC changes, including the trust certificate");
                string seen = null;
                p.Act.BeforeInstall = () => { var r = p.Ctx.Ledger.ReadAll().First().Record; var s = r.Steps.Last(); seen = r.State + "/" + s.Name + "/" + (s.EndedUtc == null ? "open" : "ended"); };
                var o = DriverSetup.Run(p.Ctx);
                Check(seen == "open/install/open", "the record and its install step are on disk before the action starts (" + seen + ")");
                var rec = o.Record;
                Check(o.Result == SetupResult.Installed && o.Message == DriverText.SetupDoneConnected && rec.State == "finished" && !rec.Incomplete && rec.OwnedPackage != null
                      && rec.BoundByOperation.Count == 1 && rec.IntroducedCertificates.Count == 2 && rec.IntroducedCertificates.All(c => c.Thumbprint == p.Act.LastThumbprint),
                      "setup read back: installed, one owned package, the console bound by it, the new certificate in both stores (" + o.Result + ", " + o.Message + ")");
                Check(rec.Before != null && rec.After != null && rec.Before.Packages.All(x => x.PublishedName != rec.OwnedPackage) && rec.After.Package(rec.OwnedPackage) != null
                      && rec.Reported.Reported == Reported.Success && rec.Steps.Select(s => s.Name).SequenceEqual(new[] { "install", "read-back" }) && rec.Elevation == "CanElevate" && rec.PcId == p.Pc.Pc,
                      "the record keeps before/after, the report, the steps, the elevation state and this PC's id");
                var back = DriverLedger.Load(rec.File);
                Check(back.OwnedPackage == rec.OwnedPackage && back.IntroducedCertificates.Count == 2 && back.Result == SetupResult.Installed && back.After.Devices.Count == 1
                      && Json.Write(back.ToJson()) == Json.Write(rec.ToJson()), "the record reads back from disk exactly");
                Check(DriverSetup.Assess(p.Pc).Kind == AssociationKind.PinnedHakchi, "after setup, the PC has the pinned Hakchi association");
                var close = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(close.Kind == CloseKind.OfferRemoval && close.Title == DriverText.CloseTitle && close.Body == DriverText.CloseBody && close.Buttons.SequenceEqual(new[] { "No — Keep Driver", "Yes — Remove Driver", "Cancel" })
                      && close.DefaultButton == 0 && close.Decision.Plan.PublishedName == rec.OwnedPackage && close.Decision.Plan.Certificates.Count == 2 && close.Decision.Plan.Problems().Count == 0,
                      "close: removal offered (owner's title, body, buttons; Keep is the default; the plan names one package and exact thumbprints)");
                var before = Unrelated(p.Pc);
                var ro = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(ro.Result == RemovalResult.Removed && p.Pc.Package(rec.OwnedPackage) == null && !p.Pc.CertificateList.Any(c => c.Thumbprint == p.Act.LastThumbprint) && Unrelated(p.Pc) == before
                      && ro.Message.Contains(DriverText.Removed) && ro.Message.Contains(DriverText.CertificateRemoved) && ro.Message.Contains(DriverText.RemovedLogsRemain),
                      "removal: exactly that package and certificate are gone (read back), nothing else changed, and it says logs remain (" + ro.Message + ")");
                var after = DriverLedger.Load(rec.File);
                Check(after.Removal == RemovalResult.Removed && after.RemovalState == "finished" && after.CloseChoice == "remove" && after.RemovalBefore != null && after.RemovalAfter != null && !after.Incomplete,
                      "the record keeps the removal's plan, before/after and result");
                Check(DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc).Items.Count == 0, "next start after a finished removal: nothing to explain");
            }

            // ---------------------------------------------------------- absent driver, console not connected (staged only)
            {
                var p = NewPc("absent-noconsole", consoleConnected: false);
                var o = DriverSetup.Run(p.Ctx);
                Check(o.Result == SetupResult.Installed && o.Message == DriverText.SetupDone && o.Record.BoundByOperation.Count == 0, "setup with no console connected: staged, the plain done text");
                Check(DriverSetup.AtClose(o.Record, p.Pc, new DriverUsage(), ElevationState.CanElevate).Kind == CloseKind.OfferRemoval, "a package this setup staged (no console) is still its own: removal offered");
            }

            // ---------------------------------------------------------- pre-existing associations are reused, never replaced
            {
                var p = NewPc("staged", consoleConnected: false);
                var t = SimulatedDriverStore.FakeThumbprint("hakchi-earlier");
                p.Pc.AddCertificate(CertStore.Root, t, PinnedDriver.CertificateSubject, "libwdi"); p.Pc.AddCertificate(CertStore.TrustedPublisher, t, PinnedDriver.CertificateSubject, "libwdi");
                var staged = p.Pc.AddPinnedPackage(t);
                var a = DriverSetup.Assess(p.Pc);
                Check(a.Kind == AssociationKind.PinnedHakchi && a.StagedOnly && a.Reusable && !a.SetupNeeded && a.Message == DriverText.PreExisting,
                      "already staged package (console absent): pre-existing, reused (" + a.Kind + ")");
                var o = DriverSetup.Run(p.Ctx);
                Check(o.Result == SetupResult.NotNeeded && p.Act.Installs == 0 && RecordFiles(p).Count == 0, "setup is not run over a staged package (no action, no setup record)");
                var reuse = DriverSetup.RecordReuse(p.Ctx, a);
                var close = DriverSetup.AtClose(reuse, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(reuse.Kind == "reuse" && close.Kind == CloseKind.Message && close.Message == "Workbench used a USB driver already on this PC. It will leave that driver in place.",
                      "close after reuse: the pre-existing text, no removal offered");
                Check(Only(Decide(p, reuse), RetainReason.PreExisting), "a reuse record is never eligible for removal");
                // a crafted record claiming the earlier Hakchi package: never removable
                var fake = DriverLedger.Load(reuse.File); fake.Kind = "setup"; fake.Plan = DriverSetupPlan.PinnedHakchi(); fake.Result = SetupResult.Installed; fake.OwnedPackage = staged.PublishedName; fake.IntroducedPackages.Add(staged.Copy());
                Check(Only(Decide(p, fake), RetainReason.PreExisting), "a prior Hakchi package (present before) is never removable, whatever a record claims");
            }
            {
                var p = NewPc("hakchi-bound");
                var t = SimulatedDriverStore.FakeThumbprint("hakchi-bound");
                var pk = p.Pc.AddPinnedPackage(t); p.Pc.Bind(p.Pc.DeviceList[0], pk);
                var a = DriverSetup.Assess(p.Pc);
                Check(a.Kind == AssociationKind.PinnedHakchi && !a.StagedOnly && a.Device != null && a.Message == DriverText.PreExisting && DriverSetup.Run(p.Ctx).Result == SetupResult.NotNeeded && p.Act.Installs == 0,
                      "already Hakchi-bound console: reused as it is");
            }
            {
                var p = NewPc("zadig-winusb");
                var pk = p.Pc.AddPackage("nes_fel.inf", "libwdi", "WinUSB", "{1B5D0E8A-0000-4000-8000-123456789ABC}", SimulatedDriverStore.FakeThumbprint("zadig"), PinnedDriver.HardwareId);
                p.Pc.Bind(p.Pc.DeviceList[0], pk);
                var a = DriverSetup.Assess(p.Pc);
                Check(a.Kind == AssociationKind.CompatibleWinUsb && a.Reusable && a.Notes.Any(n => n.Contains("not the one Hakchi2 CE 3.9.3 sets up")) && DriverSetup.Run(p.Ctx).Result == SetupResult.NotNeeded,
                      "WinUSB with a different interface GUID: compatible, reused, and noted as not the pinned association");
            }
            foreach (var (svc, kind, label) in new[] { ("libusbK", AssociationKind.LibUsbK, "libusbK"), ("libusb0", AssociationKind.LibUsb0, "libusb-win32"), ("usbccgp", AssociationKind.OtherDriver, "usbccgp") })
            {
                var p = NewPc("other-" + svc);
                var pk = p.Pc.AddPackage(svc + "_fel.inf", "libwdi", svc, svc == "libusbK" ? "{2B5D0E8A-0000-4000-8000-123456789ABC}" : null, SimulatedDriverStore.FakeThumbprint(svc), PinnedDriver.HardwareId);
                p.Pc.Bind(p.Pc.DeviceList[0], pk);
                var a = DriverSetup.Assess(p.Pc); var o = DriverSetup.Run(p.Ctx);
                Check(a.Kind == kind && !a.Reusable && !a.SetupNeeded && a.Message == string.Format(DriverText.IncompatibleFormat, label) && o.Result == SetupResult.Blocked && p.Act.Installs == 0 && p.Pc.DeviceList[0].InfPath == pk.PublishedName,
                      "another tool's " + svc + " binding: not reused, never replaced (" + a.Message + ")");
            }
            {
                var p = NewPc("inbox-winusb");
                p.Pc.Bind(p.Pc.DeviceList[0], p.Pc.InboxWinUsb(), withInterface: false);
                var a = DriverSetup.Assess(p.Pc);
                Check(a.Kind == AssociationKind.WinUsbWithoutInterface && !a.SetupNeeded && a.Message == DriverText.WinUsbWithoutInterface && DriverSetup.Run(p.Ctx).Result == SetupResult.Blocked && p.Act.Installs == 0,
                      "Windows' inbox WinUSB bound without an interface GUID: explained, not changed");
                // a crafted record claiming the inbox package
                var rec = Installed(NewPc("inbox-claim"));
                var inbox = p.Pc.InboxWinUsb().Copy();
                rec.OwnedPackage = inbox.PublishedName; rec.IntroducedPackages = new List<DriverPackage> { inbox };
                Check(Eligibility.Evaluate(rec, DriverSnapshot.Capture(p.Pc), new DriverUsage()).Reasons.Contains(RetainReason.InboxDriver), "inbox WinUSB is never removable, whatever a record claims");
                var bad = new RemovalPlan { PublishedName = "winusb.inf", InfSha256 = "a", CatalogSha256 = "b" };
                Check(bad.Problems().Count > 0 && new RemovalPlan { PublishedName = PinnedDriver.HardwareId, InfSha256 = "a", CatalogSha256 = "b" }.Problems().Count > 0
                      && new RemovalPlan { PublishedName = "oem*.inf", InfSha256 = "a", CatalogSha256 = "b" }.Problems().Count > 0
                      && new RemovalPlan { PublishedName = "oem12.inf", InfSha256 = "a", CatalogSha256 = "b", Certificates = { new CertificateEntry { Store = CertStore.Root, Thumbprint = PinnedDriver.CertificateSubject } } }.Problems().Count > 0,
                      "a removal plan can name only one published oemNN.inf and exact thumbprints: inbox INF, hardware ID, wildcard and subject name are all refused");
                var threw = false; try { p.Act.Remove(bad, ElevationState.Elevated); } catch (ArgumentException) { threw = true; }
                Check(threw && p.Pc.InboxWinUsb() != null, "the simulated removal refuses an invalid plan before changing anything");
            }

            // ---------------------------------------------------------- an existing certificate with the pinned subject blocks the pinned setup
            {
                var p = NewPc("cert-conflict");
                var t = SimulatedDriverStore.FakeThumbprint("left-behind");
                p.Pc.AddCertificate(CertStore.Root, t, PinnedDriver.CertificateSubject, "libwdi");
                var a = DriverSetup.Assess(p.Pc, DriverSetupPlan.PinnedHakchi()); var o = DriverSetup.Run(p.Ctx);
                Check(a.SetupBlocked && !a.SetupNeeded && o.Result == SetupResult.Blocked && o.Message == DriverText.CertificateConflict && p.Act.Installs == 0 && p.Pc.CertificateList.Any(c => c.Thumbprint == t),
                      "a certificate with the pinned subject already there: the setup (which deletes by subject) is not run; the certificate stays");
                var w = DriverSetup.Assess(p.Pc);
                Check(w.SetupNeeded && !w.SetupBlocked && w.Message == DriverText.SetupBody, "Workbench's own package deletes nothing by subject, so that certificate does not block it");
            }

            // ---------------------------------------------------------- refused, canceled, failed, misleading reports: the read-back decides
            foreach (var (mode, want, text) in new[] {
                (InstallBehavior.ElevationRefused, SetupResult.ElevationRefused, DriverText.SetupRefused + " " + DriverText.NothingChanged),
                (InstallBehavior.Canceled, SetupResult.Canceled, DriverText.SetupCanceled + " " + DriverText.NothingChanged),
                (InstallBehavior.ReportsSuccessNothingChanged, SetupResult.ReportedButMissing, DriverText.SetupReportedButMissing + " " + DriverText.NothingChanged) })
            {
                var p = NewPc("mode-" + mode); p.Act.InstallMode = mode;
                var o = DriverSetup.Run(p.Ctx);
                Check(o.Result == want && o.Message == text && o.Record.State == "finished" && o.Record.Changes.Count == 0 && o.Record.OwnedPackage == null
                      && DriverSetup.AtClose(o.Record, p.Pc, new DriverUsage(), ElevationState.CanElevate).Kind == CloseKind.Nothing,
                      mode + ": " + want + ", nothing changed, nothing offered at close (" + o.Message + ")");
            }
            {
                var p = NewPc("fails"); p.Act.InstallMode = InstallBehavior.Fails;
                var o = DriverSetup.Run(p.Ctx);
                Check(o.Result == SetupResult.Failed && o.Message == string.Format(DriverText.SetupFailedFormat, "WDI_ERROR_NOT_FOUND") + " " + DriverText.NothingChanged, "a failed setup: the reason and 'nothing changed' (" + o.Message + ")");
            }
            {
                var p = NewPc("lies-failure"); p.Act.InstallMode = InstallBehavior.ReportsFailureButInstalled;
                var o = DriverSetup.Run(p.Ctx);
                Check(o.Result == SetupResult.Installed && o.Record.Reported.Reported == Reported.Failed, "an exit code that says failure while the driver is there: the read-back wins (installed)");
            }
            {
                var p = NewPc("partial"); p.Act.InstallMode = InstallBehavior.FailsAfterCertificate;
                var o = DriverSetup.Run(p.Ctx);
                var close = DriverSetup.AtClose(o.Record, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(o.Result == SetupResult.Partial && o.Message.Contains("certificate") && o.Record.OwnedPackage == null && o.Record.OtherNewCertificates.Count == 2
                      && close.Kind == CloseKind.Message && close.Message == DriverText.Kept(DriverText.Because(RetainReason.SetupNotConfirmed)) && p.Pc.CertificateList.Count(c => c.Subject == PinnedDriver.CertificateSubject) == 2,
                      "setup stopped after adding its certificate: partial, the changes listed, kept (" + o.Message + " / " + close.Message + ")");
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Status == "partial" && rc.Items[0].Message.StartsWith("An earlier USB driver setup did not finish."), "next start explains the partial setup's remaining changes");
            }
            {
                var p = NewPc("two-new");
                p.Act.BeforeInstall = () => p.Pc.AddPackage("someone_else.inf", "libwdi", "WinUSB", PinnedDriver.InterfaceGuid, SimulatedDriverStore.FakeThumbprint("concurrent"), PinnedDriver.HardwareId);
                var o = DriverSetup.Run(p.Ctx);
                var close = DriverSetup.AtClose(o.Record, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(o.Result == SetupResult.InstalledNotOwned && o.Message == DriverText.SetupDoneNotOwned && o.Record.OwnedPackage == null && o.Record.Ownership.Contains("not exactly one")
                      && close.Kind == CloseKind.Message && close.Message == DriverText.Kept(DriverText.Because(RetainReason.OwnershipUncertain)) && Only(Decide(p, o.Record), RetainReason.OwnershipUncertain),
                      "two packages appeared during setup: the driver works, ownership is not claimed, nothing is offered (" + o.Result + " / " + close.Message + ")");
            }

            // ---------------------------------------------------------- restart pending
            {
                var p = NewPc("restart"); p.Act.InstallMode = InstallBehavior.SuccessRestartPending;
                var o = DriverSetup.Run(p.Ctx);
                var close = DriverSetup.AtClose(o.Record, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(o.Result == SetupResult.InstalledRestartPending && o.Message == DriverText.SetupRestart && close.Kind == CloseKind.Message && close.Message == DriverText.Kept(DriverText.Because(RetainReason.RestartPending)),
                      "setup waiting for a restart: said plainly (Workbench does not restart), and removal is not offered meanwhile");
            }
            {
                var p = NewPc("removal-restart"); var rec = Installed(p); p.Act.RemoveMode = RemoveBehavior.RestartPending;
                var ro = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(ro.Result == RemovalResult.RemovedRestartPending && ro.Message == DriverText.RemovalRestart + " " + DriverText.CertificateKeptUntilFinished && !ro.Message.Contains(DriverText.Removed)
                      && p.Pc.CertificateList.Count(c => c.Thumbprint == p.Act.LastThumbprint) == 2 && DriverLedger.Load(rec.File).CleanupState == "deferred",
                      "a removal waiting for a restart is never called finished; its certificate stays (both stores) and its cleanup is deferred");
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Status == "removal-waiting-for-restart" && rc.Items[0].Message == DriverText.ReconcileWaitingForRestart + " " + DriverText.ReconcileCertificateUntilRestart,
                      "next start: still waiting for the restart (" + rc.Items.FirstOrDefault()?.Message + ")");
                p.Pc.SimulateRestart();   // the PC restarted: Windows finished the removal
                var rc2 = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc2.Items.Count == 1 && rc2.Items[0].Status == "cleanup-ready" && rc2.Items[0].Message == DriverText.ReconcileCleanupReady, "after the restart finished it: the kept certificate is offered for removal");
                var co = DriverSetup.CleanUp(p.Ctx, DriverLedger.Load(rec.File), new DriverUsage());
                Check(co.Result == CleanupResult.Removed && p.Act.Cleanups == 1 && !p.Pc.CertificateList.Any(c => c.Thumbprint == p.Act.LastThumbprint) && DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc).Items.Count == 0,
                      "after the cleanup: the certificate is gone and there is nothing to explain");
            }

            // ---------------------------------------------------------- crashes: incomplete records keep everything
            {
                var p = NewPc("crash-setup"); p.Act.InstallMode = InstallBehavior.CrashAfterChanges;
                var crashed = false; try { DriverSetup.Run(p.Ctx); } catch (SimulatedCrashException) { crashed = true; }
                var rec = p.Ctx.Ledger.ReadAll().Single().Record;
                Check(crashed && rec.State == "open" && rec.Steps.Single().Name == "install" && rec.Steps.Single().EndedUtc == null && rec.Incomplete,
                      "ledger written, then a crash during setup: the record shows the step begun and never ended");
                Check(Only(Decide(p, rec), RetainReason.RecordIncomplete), "an incomplete setup record is never eligible for removal");
                var close = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(close.Kind == CloseKind.Message && close.Message == DriverText.Kept(DriverText.Because(RetainReason.RecordIncomplete)), "close with an incomplete record: kept, with the reason (" + close.Message + ")");
                var hashes = RecordFiles(p).ToDictionary(f => f, f => Sha(f)); var pkgs = p.Pc.PackageList.Count; var certs = p.Pc.CertificateList.Count;
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Status == "incomplete-setup" && rc.Items[0].DriverStillOnPc
                      && rc.Items[0].Message == DriverText.ReconcileIncompleteSetup + " " + DriverText.ReconcileDriverPresent + " " + DriverText.Kept(DriverText.Because(RetainReason.RecordIncomplete)),
                      "next start explains the interrupted setup: the driver is there and was kept (" + rc.Items.FirstOrDefault()?.Message + ")");
                Check(RecordFiles(p).All(f => hashes.ContainsKey(f) && hashes[f] == Sha(f)) && RecordFiles(p).Count == hashes.Count && p.Pc.PackageList.Count == pkgs && p.Pc.CertificateList.Count == certs,
                      "the startup check is read-only: no record and nothing on the PC changed");
            }
            {
                var p = NewPc("crash-before"); p.Act.InstallMode = InstallBehavior.CrashAfterChanges;
                p.Act.BeforeInstall = () => throw new SimulatedCrashException("before anything changed");
                try { DriverSetup.Run(p.Ctx); } catch (SimulatedCrashException) { }
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Message == DriverText.ReconcileIncompleteSetup + " " + DriverText.ReconcileDriverAbsent && !rc.Items[0].DriverStillOnPc,
                      "a crash before anything changed: next start says the driver is not there (" + rc.Items.FirstOrDefault()?.Message + ")");
            }
            {
                var p = NewPc("crash-removal"); var rec = Installed(p); p.Act.RemoveMode = RemoveBehavior.CrashAfterPackage;
                try { DriverSetup.Remove(p.Ctx, rec, new DriverUsage()); } catch (SimulatedCrashException) { }
                var loaded = DriverLedger.Load(rec.File);
                Check(loaded.RemovalState == "open" && loaded.Incomplete && Decide(p, loaded).Reasons.Contains(RetainReason.RemovalIncomplete), "a crash during removal: the record shows it unfinished; nothing more is offered");
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Status == "incomplete-removal" && rc.Items[0].Message.Contains(DriverText.ReconcileRemovalFinished) && rc.Items[0].Message.Contains(DriverText.CertificateNotRemoved)
                      && rc.Items[0].Message.Contains(DriverText.ReconcileOfferAfterRestart) && DriverSetup.CleanUp(p.Ctx, loaded, new DriverUsage()).Result == CleanupResult.NotEligible
                      && p.Pc.CertificateList.Count(c => c.Thumbprint == p.Act.LastThumbprint) == 2,
                      "next start explains what the interrupted removal left (the certificate), and no cleanup before a restart (" + rc.Items.FirstOrDefault()?.Message + ")");
                p.Pc.SimulateRestart();
                var rc2 = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc); var co = DriverSetup.CleanUp(p.Ctx, DriverLedger.Load(rec.File), new DriverUsage());
                Check(rc2.Items.Single().Status == "cleanup-ready" && co.Result == CleanupResult.Removed && !p.Pc.CertificateList.Any(c => c.Thumbprint == p.Act.LastThumbprint)
                      && DriverLedger.Load(rec.File).RemovalState == "open", "after a restart: the certificate the interrupted removal planned is offered and removed; the removal itself stays recorded as unfinished");
            }

            // ---------------------------------------------------------- removal refused, failed, unavailable
            {
                var p = NewPc("remove-refused"); var rec = Installed(p); p.Act.RemoveMode = RemoveBehavior.ElevationRefused;
                var ro = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(ro.Result == RemovalResult.ElevationRefused && ro.Message == "The USB driver was kept because Windows did not give administrator permission. No other driver was removed." && p.Pc.Package(rec.OwnedPackage) != null,
                      "removal refused at the administrator prompt: kept, said plainly (" + ro.Message + ")");
                p.Act.RemoveMode = RemoveBehavior.Fails;
                var rf = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(rf.Result == RemovalResult.Failed && rf.Message == "The USB driver was kept because Windows could not remove it (Access is denied.). No other driver was removed.", "removal failed: kept, with Windows' reason (" + rf.Message + ")");
                var real = new SetupContext { Store = p.Pc, Actions = new WindowsDriverActions(), Ledger = p.Ctx.Ledger };
                var ru = DriverSetup.Remove(real, rec, new DriverUsage());
                Check(ru.Result == RemovalResult.Unavailable && ru.Message == DriverText.Kept(DriverText.Because(RetainReason.ActionUnavailable)) && p.Pc.Package(rec.OwnedPackage) != null, "this build's real removal is closed: kept");
            }

            // ---------------------------------------------------------- each reason removal is not offered
            {
                var p = NewPc("shared"); var rec = Installed(p);
                var other = p.Pc.AddDevice("5&99&0&4", false); p.Pc.Bind(other, p.Pc.Package(rec.OwnedPackage));   // the console on another USB port, or another device
                var close = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(Only(Decide(p, rec), RetainReason.SharedWithOtherDevice) && close.Message == "The USB driver was kept because another USB device on this PC also uses it. No other driver was removed.",
                      "another device instance shares the package: kept (" + close.Message + ")");
            }
            {
                var p = NewPc("changed"); var rec = Installed(p);
                p.Pc.Package(rec.OwnedPackage).InfSha256 = SimulatedDriverStore.FakeHash("restaged by another program");
                Check(Only(Decide(p, rec), RetainReason.PackageChanged), "the package changed since setup: kept");
            }
            {
                var p = NewPc("missing"); var rec = Installed(p);
                p.Pc.PackageList.RemoveAll(x => x.PublishedName == rec.OwnedPackage);
                var close = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.CanElevate); var ro = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(close.Kind == CloseKind.Message && close.Message == DriverText.RemovalGone && ro.Result == RemovalResult.NotEligible && ro.Message == DriverText.RemovalGone && p.Act.Removals == 0,
                      "the package is already gone: nothing offered, nothing run");
            }
            {
                var p = NewPc("usage"); var rec = Installed(p);
                var cases = new (string what, DriverUsage u, RetainReason r)[]
                {
                    ("a console write in progress", new DriverUsage { ConsoleWriteInProgress = true }, RetainReason.ConsoleWriteInProgress),
                    ("an unsettled console result", new DriverUsage { UnresolvedConsoleResult = true }, RetainReason.UnresolvedConsoleResult),
                    ("a console operation running", new DriverUsage { ConsoleOperationActive = true }, RetainReason.ConsoleOperationActive),
                    ("embedded: the parent app still needs it", new DriverUsage { Host = HostKind.Embedded, ParentAppNeedsDevice = true }, RetainReason.ParentAppNeedsIt),
                    ("another Workbench operation", new DriverUsage { OtherWorkbenchOperation = true }, RetainReason.AnotherWorkbenchOperation),
                    ("Hakchi open", new DriverUsage { OtherProgramsOpen = { "Hakchi" } }, RetainReason.OtherProgramMayUseIt),
                };
                foreach (var (what, u, r) in cases)
                {
                    var close = DriverSetup.AtClose(rec, p.Pc, u, ElevationState.CanElevate);
                    var ro = DriverSetup.Remove(p.Ctx, rec, u);
                    Check(Only(Decide(p, rec, u), r) && close.Kind == CloseKind.Message && close.Message == DriverText.Kept(DriverText.Because(r)) && ro.Result == RemovalResult.NotEligible && p.Act.Removals == 0,
                          what + ": not offered, and a removal call is refused too (" + close.Message + ")");
                }
                Check(DriverSetup.AtClose(rec, p.Pc, new DriverUsage { Host = HostKind.Embedded, ParentAppNeedsDevice = false }, ElevationState.CanElevate).Kind == CloseKind.OfferRemoval,
                      "embedded with the parent app no longer needing it: removal may be offered");
                p.Pc.FailReads = true;
                var cu = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.CanElevate);
                Check(cu.Message == DriverText.Kept(DriverText.Because(RetainReason.StateUnreadable)) && DriverSetup.Assess(p.Pc).Kind == AssociationKind.Unreadable && DriverSetup.Run(p.Ctx).Result == SetupResult.Blocked,
                      "the PC's driver list cannot be read: kept, and no setup either (" + cu.Message + ")");
                p.Pc.FailReads = false; p.Pc.Pc = "sim-pc-0002";
                Check(Only(Decide(p, rec), RetainReason.OtherPc), "a record from another PC is never acted on");
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc.Items.Count == 1 && rc.Items[0].Status == "other-pc" && rc.Items[0].Message == DriverText.ReconcileOtherPc, "next start on another PC: nothing compared or changed");
            }
            {
                var p = NewPc("crafted"); var rec = Installed(p);
                var r1 = DriverLedger.Load(rec.File); r1.Before.Packages.Add(r1.IntroducedPackages[0].Copy());
                Check(Only(Decide(p, r1), RetainReason.PreExisting), "the same package in the before-state (pre-staged): pre-existing");
                var r2 = DriverLedger.Load(rec.File); r2.Before.Packages.Add(p.Pc.Package(rec.OwnedPackage).Copy()); r2.Before.Packages.Last().PublishedName = "oem7.inf"; r2.Before.Packages.Last().InfSha256 = "different";
                Check(Only(Decide(p, r2), RetainReason.OwnershipUncertain), "an earlier package of the same kind was there: ownership not shown");
                var r3 = DriverLedger.Load(rec.File); r3.OwnedPackage = null;
                Check(Only(Decide(p, r3), RetainReason.OwnershipUncertain), "an installed record without an owned package: not offered");
                var r4 = DriverLedger.Load(rec.File); r4.IntroducedPackages[0].Provider = "Contoso";
                Check(Only(Decide(p, r4), RetainReason.OtherToolPackage), "a package that is not the planned identity: another program's, never removed");
                var r5 = DriverLedger.Load(rec.File); r5.Result = SetupResult.Partial;
                Check(Only(Decide(p, r5), RetainReason.SetupNotConfirmed), "a setup not confirmed by its read-back: not offered");
                var r6 = DriverLedger.Load(rec.File); r6.Before.Certificates.Add(r6.IntroducedCertificates[0]);
                var d6 = Decide(p, r6);
                Check(d6.Offer && d6.CertificatesKept.Any(k => k.Why == RetainReason.CertificatePreExisting) && d6.Plan.Certificates.Count == 1 && d6.Plan.Certificates[0].Store == CertStore.TrustedPublisher,
                      "a certificate already in a store before: that one stays (the package and the other store's new copy may go)");
            }
            {
                var p = NewPc("cert-shared"); var rec = Installed(p);
                p.Pc.AddPackage("another_libwdi.inf", "libwdi", "WinUSB", "{3B5D0E8A-0000-4000-8000-123456789ABC}", p.Act.LastThumbprint, @"USB\VID_1234&PID_5678");
                var d = Decide(p, rec);
                Check(d.Offer && d.Plan.Certificates.Count == 0 && d.CertificatesKept.Count == 2 && d.CertificatesKept.All(k => k.Why == RetainReason.CertificateShared), "a certificate another package is signed with: the package may go, the certificate stays");
                var ro = DriverSetup.Remove(p.Ctx, rec, new DriverUsage());
                Check(ro.Result == RemovalResult.Removed && p.Pc.CertificateList.Count(c => c.Thumbprint == p.Act.LastThumbprint) == 2
                      && ro.Message.Contains(string.Format(DriverText.CertificateKeptFormat, DriverText.Because(RetainReason.CertificateShared))), "removal leaves the shared certificate and says why (" + ro.Message + ")");
                var r = DriverLedger.Load(rec.File); var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(r.CleanupState == "deferred" && r.DeferredCertificates.Count == 2 && !r.CleanupRestartFirst && rc.Items.Single().Status == "cleanup-deferred"
                      && rc.Items.Single().Message == string.Format(DriverText.ReconcileCleanupKeptFormat, DriverText.Because(RetainReason.CertificateShared)),
                      "the shared certificate is a deferred cleanup, explained at the next start (" + rc.Items.Single().Message + ")");
                p.Pc.PackageList.RemoveAll(x => x.OriginalName == "another_libwdi.inf");
                Check(DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc).Items.Single().Status == "cleanup-ready" && DriverSetup.CleanUp(p.Ctx, DriverLedger.Load(rec.File), new DriverUsage()).Result == CleanupResult.Removed
                      && !p.Pc.CertificateList.Any(c => c.Thumbprint == p.Act.LastThumbprint), "once no other package is signed with it: offered and removed");
            }
            {
                var p = NewPc("cert-scan"); var rec = Installed(p); p.Pc.IncompleteSignerScan = true;
                var d = Decide(p, rec);
                Check(d.Offer && d.Plan.Certificates.Count == 0 && d.CertificatesKept.All(k => k.Why == RetainReason.CertificateSharingUnknown), "not every package catalog could be checked: the certificate stays");
                p.Pc.IncompleteSignerScan = false; p.Pc.CertificateList.First(c => c.Thumbprint == p.Act.LastThumbprint && c.Store == CertStore.Root).HasPrivateKey = true;
                var d2 = Decide(p, rec);
                Check(d2.Offer && d2.CertificatesKept.Single().Why == RetainReason.CertificateChanged && d2.Plan.Certificates.Single().Store == CertStore.TrustedPublisher, "a certificate that changed (it now has a private key): it stays");
            }

            // ---------------------------------------------------------- the real actions are closed in this version (DriverChanges, Gate.cs)
            {
                var p = NewPc("real-closed");
                var real = new WindowsDriverActions();
                string msg = null; try { real.Install(DriverSetupPlan.CcsWinUsb(), ElevationState.Elevated); } catch (DriverActionUnavailableException ex) { msg = ex.Message; }
                var o = DriverSetup.Run(new SetupContext { Store = p.Pc, Actions = real, Ledger = p.Ctx.Ledger });
                Check(msg != null && msg.StartsWith("Setting up or removing the USB driver on this PC is not available in this version.") && !real.Available && o.Result == SetupResult.Unavailable
                      && o.Message == DriverText.SetupUnavailableNote && RecordFiles(p).Count == 0 && p.Pc.PackageList.Count(x => !x.IsInbox) == 1,
                      "the real setup is closed by the DriverChanges boundary ('" + msg + "'); Run changes nothing and writes no record");
            }

            // ---------------------------------------------------------- keep, and the startup check after a kept setup; unreadable records
            {
                var p = NewPc("keep"); var rec = Installed(p);
                DriverSetup.Keep(p.Ctx, rec);
                var loaded = DriverLedger.Load(rec.File);
                var rc = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(loaded.CloseChoice == "kept" && p.Pc.Package(rec.OwnedPackage) != null && rc.Items.Count == 1 && rc.Items[0].Status == "installed"
                      && rc.Items[0].Message == string.Format(DriverText.ReconcileInstalledFormat, rec.StartedUtc.Split('T')[0]), "Keep Driver: recorded; next start says it is still in place (" + rc.Items.FirstOrDefault()?.Message + ")");
                File.WriteAllText(Path.Combine(p.Ctx.Ledger.Folder, "usb-driver-99999999-999999-broken00.json"), "{ not json");
                var rc2 = DriverSetup.Reconcile(p.Ctx.Ledger, p.Pc);
                Check(rc2.Items.Any(i => i.Status == "unreadable" && i.Message.StartsWith("A USB driver record could not be read (")) && rc2.Items.Any(i => i.Status == "installed"), "an unreadable record is reported, never acted on");
                var close = DriverSetup.AtClose(rec, p.Pc, new DriverUsage(), ElevationState.Elevated);
                Check(close.Body == DriverText.CloseBodyFor(ElevationState.Elevated) && !close.Body.Contains("Administrator permission is required"), "close text for an already elevated person does not say permission must be asked for");
            }
        }

        static void Texts()
        {
            Check(DriverText.SetupTitle == "USB driver setup required"
                  && DriverText.SetupBody == "Workbench needs a Windows USB driver to communicate with your NES Classic. Administrator permission is required. This sets up the connection on this PC; it does not install anything on the console."
                  && DriverText.SetupKeepOrRemove == "Keep the driver for next time, or choose to remove it when Workbench closes if it was installed by Workbench. Removing it may mean setting up the driver again for Workbench or Hakchi."
                  && DriverText.SetupButton == "Set Up Driver" && DriverText.SetupCancelButton == "Cancel", "setup dialog: the owner's title, body and buttons");
            Check(DriverText.CloseTitle == "Remove the USB driver?"
                  && DriverText.CloseBody == "Workbench installed this driver on this PC. Removing it may require driver setup again in Workbench or Hakchi. Administrator permission is required. Your console and backup files will not be changed."
                  && DriverText.KeepButton == "No — Keep Driver" && DriverText.RemoveButton == "Yes — Remove Driver" && DriverText.CloseCancelButton == "Cancel" && DriverText.CloseDefaultButton == 0,
                  "close dialog: the owner's title, body and buttons, Keep the default");
            Check(DriverText.PreExisting == "Workbench used a USB driver already on this PC. It will leave that driver in place."
                  && DriverText.Kept("x") == "The USB driver was kept because x. No other driver was removed.", "pre-existing and kept texts");
            var el = DriverText.SetupBodyFor(ElevationState.Elevated);
            Check(DriverText.SetupBodyFor(ElevationState.CanElevate) == DriverText.SetupBody && DriverText.SetupBodyFor(ElevationState.Unknown) == DriverText.SetupBody
                  && !el.Contains("Administrator permission is required") && !el.ToLowerInvariant().Contains("ask") && el.Contains("already has administrator permission")
                  && DriverText.SetupBodyFor(ElevationState.StandardUser).Contains("administrator's name and password"), "elevation: an elevated person is not told Windows will ask; a standard user is told what Windows asks for");
            Check(Enum.GetValues(typeof(RetainReason)).Cast<RetainReason>().All(r => DriverText.Because(r) != "Workbench could not show that removing it is safe" && !DriverText.Because(r).EndsWith(".")),
                  "every retention reason has its own plain words");
            var all = typeof(DriverText).GetFields().Where(f => f.IsLiteral && f.FieldType == typeof(string)).Select(f => (string)f.GetRawConstantValue()).Concat(DriverText.PinnedHelperChanges)
                .Concat(Enum.GetValues(typeof(RetainReason)).Cast<RetainReason>().Select(DriverText.Because)).ToList();
            var uk = new[] { "colour", "behaviour", "recognise", "organise", "licence", "cancelled", "favourite", "analyse", "centre" };
            Check(all.All(t => !uk.Any(w => t.ToLowerInvariant().Contains(w))), "US English in every driver text");
        }

        static void InfAndIds()
        {
            Check(UsbId.Matches(@"USB\VID_1F3A&PID_EFE8&REV_0100", 0x1F3A, 0xEFE8) && UsbId.Matches(@"usb\vid_1f3a&pid_efe8", 0x1F3A, 0xEFE8) && !UsbId.Matches(@"USB\VID_1F3A&PID_EFE80", 0x1F3A, 0xEFE8)
                  && !UsbId.Matches(@"USB\VID_1F3A&PID_EFE9", 0x1F3A, 0xEFE8) && UsbId.IsPublishedName("oem206.inf") && !UsbId.IsPublishedName("winusb.inf") && !UsbId.IsPublishedName("oem*.inf"),
                  "USB identity and published-name matching are exact");
            // the INF libwdi writes for the pinned helper (winusb.inf.in at 6d379a3, tokens filled as classic-driver.c fills them), saved as UTF-16 with a byte order mark
            var inf = string.Join("\r\n", new[] {
                "; nintendo_classic.inf", "; Copyright (c) 2010-2016 Pete Batard <pete@akeo.ie> (GNU LGPL)", "[Strings]", "DeviceName = \"Nintendo Classic\"", "VendorName = \"Nintendo\"",
                "SourceName = \"Nintendo Classic Install Disk\"", "DeviceID   = \"VID_1F3A&PID_EFE8\"", "DeviceGUID = \"{409ADFB6-9503-4D0B-BDDF-C2BD419E0F60}\"", "",
                "[Version]", "Signature   = \"$Windows NT$\"", "Class       = \"USBDevice\"", "ClassGuid   = {88bae032-5a81-49f0-bc3d-a4ff138216d6}", "Provider    = \"libwdi\"",
                "CatalogFile = nintendo_classic.cat", "DriverVer   = 11/07/2009, 6.1.7600.16385", "", "[Manufacturer]", "%VendorName% = libusbDevice_WinUSB,NTx86,NTamd64,NTarm", "",
                "[libusbDevice_WinUSB.NTamd64]", "%DeviceName% = USB_Install, USB\\%DeviceID%", "", "[USB_Install.Services]", "Include    = winusb.inf",
                "AddService = WinUSB,0x00000002,WinUSB_ServiceInstall", "", "[USB_Install.HW]", "AddReg = AddDeviceInterfaceGUID", "", "[AddDeviceInterfaceGUID]",
                "HKR,,DeviceInterfaceGUIDs,0x10000,%DeviceGUID%", "; USB\\VID_DEAD&PID_BEEF only in a comment" });
            var bytes = new byte[] { 0xFF, 0xFE }.Concat(Encoding.Unicode.GetBytes(inf)).ToArray();
            var i = Inf.Parse(Inf.Decode(bytes), "NTamd64");
            Check(i.Provider == "libwdi" && i.CatalogFile == "nintendo_classic.cat" && i.ClassGuid == PinnedDriver.ClassGuid && i.UsbIds.SequenceEqual(new[] { PinnedDriver.HardwareId })
                  && i.InterfaceGuids.SequenceEqual(new[] { PinnedDriver.InterfaceGuid }) && i.Services.SequenceEqual(new[] { "WinUSB" }) && i.DriverVer.EndsWith("6.1.7600.16385"),
                  "the libwdi INF (UTF-16): provider, catalog, identity through %DeviceID%, interface GUID, service; a comment is ignored");
            var k = Inf.Parse("[Version]\nProvider=%P%\nCatalogFile.NTamd64=k64.cat\nCatalogFile=k.cat\n[Strings]\nP=\"libusbK\"\n[Devices.NTamd64]\n\"FEL\"=Inst, USB\\VID_1F3A&PID_EFE8&MI_00\n[Inst.Services]\nAddService=libusbK,2,Svc\n", "NTamd64");
            Check(k.Provider == "libusbK" && k.CatalogFile == "k64.cat" && k.UsbIds.Single() == @"USB\VID_1F3A&PID_EFE8&MI_00" && k.Services.Single() == "libusbK" && k.InterfaceGuids.Count == 0,
                  "another tool's INF (ANSI): decorated catalog, interface suffix, its own service");
            var tooBig = false; try { Inf.Decode(new byte[Inf.MaxBytes + 1]); } catch (FormatException) { tooBig = true; }
            Check(tooBig, "an INF over the size bound is refused");
            // a restart of Windows since a removal: Windows' start time read now is later than the removal and is not the start read then
            RestartState B(string t) => new RestartState { BootUtc = t };
            const string then = "2026-11-16T08:00:00Z", removal = "2026-11-16T10:00:00.000Z";
            Check(RestartState.RestartedSince(B("2026-11-16T10:05:00Z"), removal, then) && !RestartState.RestartedSince(B(then), removal, then)
                  && !RestartState.RestartedSince(B("2026-11-16T08:01:00Z"), removal, then) && !RestartState.RestartedSince(B("2026-11-16T09:59:59Z"), removal, then)
                  && !RestartState.RestartedSince(B(null), removal, then) && !RestartState.RestartedSince(B("2026-11-16T10:05:00Z"), null, then) && !RestartState.RestartedSince(null, removal, then)
                  && RestartState.RestartedSince(B("2026-11-16T10:05:00Z"), removal, null) && !RestartState.RestartedSince(B("2026-11-16T10:01:00Z"), removal, "2026-11-16T10:00:30Z")
                  && RestartState.From(Json.Parse(Json.Write(B(then).ToJson()))).BootUtc == then,
                  "a restart is seen only when Windows' start time is after the removal and is not the earlier start moved by a clock change; unknown times never count");
        }

        /// <summary>reads THIS PC's driver state (read only) and prints counts; runs only with --real-driver-store</summary>
        public static void DriverReal()
        {
            if (!RealDriverStore) throw new SkipException("reads this PC's driver state; give --real-driver-store to run it (prints counts only)");
            var store = new WindowsDriverStore();
            var sw = System.Diagnostics.Stopwatch.StartNew();
            var s = DriverSnapshot.Capture(store);
            var a = DriverSetup.Assess(s);
            Console.WriteLine("      read in " + sw.Elapsed.TotalSeconds.ToString("0.0") + " s: " + s.Devices.Count + " instance(s) for 1F3A:EFE8 (" + s.Devices.Count(d => d.Present) + " connected), "
                + s.Packages.Count + " relevant package(s), " + s.Certificates.Count + " relevant certificate entr(ies), restart pending: " + s.Restart.SystemPending + ", assessment: " + a.Kind);
            Check(s.Error == null, "this PC's driver state reads without error (" + (s.Error ?? "ok") + ")");
            Check(s.PcId != null && s.PcId.StartsWith("pc-") && s.PcId.Length == 27 && s.StoreSummary.Count == 2, "a non-identifying PC id and both certificate stores were read");
            Check(s.Packages.All(p => p.DeclaredIds.Count > 0 || s.Devices.Any(d => PinnedDriver.Eq(d.InfPath, p.PublishedName))), "every relevant package names the identity or is bound to it");
            var again = DriverSnapshot.Capture(store);
            Check(Json.Write(again.Packages.Select(p => p.ToJson()).ToList()) == Json.Write(s.Packages.Select(p => p.ToJson()).ToList()), "two readings agree (nothing changed by reading)");
            Check(DateTime.TryParse(s.Restart.BootUtc, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal, out var boot)
                  && boot < DateTime.UtcNow && boot > DateTime.UtcNow.AddDays(-400) && !RestartState.RestartedSince(again.Restart, s.TakenUtc, s.Restart.BootUtc),
                  "Windows' start time is read (in the past), and a second reading in the same session is not taken for a restart");
        }
    }
}
